from review import card,save,DATE
i='TCS-3678';_,c=card(i);refs=c['references'];refs[0]['locator']='Section 2, sparse effective-domain encoding; Definition 6, core; Definition 8 and Theorems 9–10, Siggers criterion; Section 2.4, Theorems 16–20 and the core-crisp open question.'
refs += [dict(id='full',title='Testing the complexity of a valued CSP language',authors='Vladimir Kolmogorov',year=2019,url='https://arxiv.org/abs/1803.02289',pdf_url='https://arxiv.org/pdf/1803.02289',locator='Full version 3, 19 April 2019; Section 2.4 repeats the core-crisp question and the conditional consequence of a uniform solver.'),dict(id='current',title='The Complexity of Finding Coset-Generating Polymorphisms and the Promise Metaproblem',authors='Manuel Bodirsky; Armin Weiß',year=2026,url='https://doi.org/10.4230/LIPIcs.ICALP.2026.169',pdf_url='https://drops.dagstuhl.de/storage/00lipics/lipics-vol374-icalp2026/LIPIcs.ICALP.2026.169/LIPIcs.ICALP.2026.169.pdf',locator='ICALP 2026, Section 4 after Theorem 4: the core promise equates Siggers and idempotent Siggers, and the latter polynomial-time test remains open. Introduction separates uniform solving from the fixed-template dichotomy.')]
notes=['Recovered a promised-core meta-decision problem with the domain and relation tables included in the input.','Defined crisp languages as explicitly listed allowed tuples, cores through unary preservation, and the full four-ary Siggers certificate.','Used the algebraic solvability predicate to avoid conflating dichotomy terminology with an assumption that P differs from NP.','Separated general-language NP-completeness, finite-valued fractional-polymorphism testing and uniform CSP solvers.','Verified an explicit July 2026 restatement of the unresolved idempotent-Siggers metaproblem.']
save(i,dict(title='Polynomial-time tractability testing for core crisp CSP languages',formal='Is there one deterministic polynomial-time algorithm that, given a finite crisp constraint language Γ over an explicitly given finite domain D and promised that Γ is a core, decides whether Γ admits an idempotent Siggers polymorphism? Equivalently on the core promise, decide whether Γ is solvable in the algebraic sense of the finite-domain CSP dichotomy. The polynomial must be uniform in the entire input, including |D|, the number of relations, their arities and their listed tuples; neither a polymorphism nor a tractability certificate is supplied.',definitions='A crisp language is a finite set Γ of relations R⊆Dʳ of possibly different finite arities on a finite nonempty explicitly listed domain D. Each relation is given by its arity and a list of its allowed tuples; unlisted tuples are forbidden. This is equivalent to a cost function with value 0 on allowed tuples and +∞ elsewhere. The input size N includes D, relation delimiters, arities and the binary encodings of all listed entries. There is no fixed bound on |D| or arity imposed outside the input. An m-ary operation g:Dᵐ→D preserves an r-ary relation R if, for every m tuples a¹,…,aᵐ∈R, the coordinatewise tuple (g(a¹₁,…,aᵐ₁),…,g(a¹ᵣ,…,aᵐᵣ)) lies in R. A polymorphism of Γ preserves every relation in Γ. The language is a core if every unary polymorphism u:D→D is bijective; for a finite relational structure such a map is an automorphism. Core status is promised rather than something the requested algorithm must verify. An idempotent Siggers polymorphism is a four-ary operation s:D⁴→D that preserves every relation and satisfies s(x,x,x,x)=x for all x∈D and s(r,a,r,e)=s(a,r,e,a) for every r,a,e∈D. On a core, existence of a Siggers operation without the idempotence identity is equivalent to existence of an idempotent one. An ordinary CSP(Γ) instance has variables and constraints requiring selected variable tuples to belong to relations of Γ; it asks for a satisfying assignment from D. In the source’s terminology, solvable means satisfying the dichotomy’s polymorphism criterion. Such languages have polynomial-time CSP algorithms when Γ is fixed; failure of the criterion gives NP-hardness. The present target tests that algebraic criterion and does not assume P≠NP in order to define its yes/no answers. The requested machine must halt in N^{O(1)} time on all inputs and be correct on every input satisfying the core promise. Its behavior on non-core inputs is unrestricted. The task only asks to decide existence, not to output the operation table, although a four-ary table has |D|⁴ entries and gives a polynomial-size, polynomially checkable existence certificate.',question_type='yes_no',answer_criterion='Give a deterministic algorithm with one polynomial running-time bound in N that accepts exactly the promised core languages having such a polymorphism, or prove that no such algorithm exists. A hardness statement requires the core promise to be respected. Testing whether the input is a core, classifying languages without that promise, or solving CSP instances for one fixed tractable template does not settle this meta-decision problem.',context_blocks=[dict(title='The promise removes a known source of hardness',text='Testing tractability for arbitrary crisp languages is NP-complete, and testing core status is itself difficult. The question assumes core status from the start; neither hardness result alone classifies the promised problem.',citation='primary'),dict(title='Finite-valued testing is a different theorem',text='Theorem 16 gives a polynomial algorithm for the relevant binary symmetric fractional polymorphism of a core finite-valued language. Crisp relations use forbidden assignments with infinite cost, so that finite-valued theorem does not provide this Siggers test.',citation='primary'),dict(title='Fixed-template solvability is weaker than a uniform solver',text='The source states that a uniform polynomial-time solver for all solvable core crisp languages would imply the desired test. The fixed-template dichotomy alone does not give a polynomial uniform in the varying input language.',citation='full'),dict(title='The 2026 metaproblem paper retains the question',text='Bodirsky and Weiß explicitly distinguish idempotent Siggers testing from the unrestricted NP-complete metaproblem and note the equivalence under the core promise. Their results on coset-generating and promise metaproblems do not give the general Siggers test.',citation='current')],why='Would make the finite-domain CSP tractability criterion efficiently recognizable when the core is already given, connecting the structural dichotomy to algorithms whose template also varies as input.',references=refs,progress=[dict(date='2019',text='The ICALP paper contrasts the solved core finite-valued test with the open core crisp test and records the uniform-solver implication.',citation='primary'),dict(date='2026',text='The ICALP metaproblem article explicitly keeps idempotent Siggers testing open and explains why unrestricted Siggers hardness does not cover it.',citation='current')],status='open',status_note='Checked the source’s encoding, core definition and algebraic solvability convention, its complete April 2019 version, and the explicit ICALP 2026 discussion following Theorem 4. Broader searches through 12 September 2026 found no polynomial core-crisp Siggers test or matching promised-core hardness result. The 2026 primary source directly supports continued openness; search is not exhaustive.',model_self_contained=True,requires_context=False,review_note='Recovered a precise polynomial-time existence test under a core promise, with all Siggers identities and relation-preservation quantifiers stated.',importance=dict(score=c['importance']['score'],method='editorial',reason='A central effective-classification question for CSP templates, separating fixed-template tractability from uniform recognition. Existing score retained.',assessed_on=DATE),working_summary=dict(sentences=['A crisp constraint language lists the allowed tuples over a finite domain, and the input is promised to be a core.','The question asks for a polynomial-time test for an idempotent four-ary Siggers polymorphism.','Both the domain and every relation are part of the input, so one uniform polynomial bound is required.','The known finite-valued test and unrestricted-language NP-hardness do not answer this promised-core question.','An ICALP 2026 article explicitly retains the relevant Siggers testing problem as open.'],basis='saved_sources',source_basis='source-text',written_on=DATE,source_refs=['primary','full','current'])),notes=notes,checked_sources=[r['url'] for r in refs])
